### Safer version

```js
class ApiError extends Error {
  constructor(message, { status, statusText, body, cause } = {}) {
    super(message);
    this.name = "ApiError";
    this.status = status;
    this.statusText = statusText;
    this.body = body;
    if (cause) this.cause = cause;
  }
}

function isJsonContentType(contentType) {
  return /^application\/(?:[^;]+\+)?json(?:\s*;|$)/i.test(contentType || "");
}

async function getUser(id, { signal, timeoutMs = 10_000 } = {}) {
  let userId;

  if (typeof id === "number") {
    if (!Number.isSafeInteger(id) || id < 0) {
      throw new TypeError("User id must be a non-negative safe integer");
    }

    userId = String(id);
  } else if (typeof id === "string") {
    userId = id.trim();
  } else {
    throw new TypeError("User id must be a string or number");
  }

  // Adjust this regex to match your real ID format.
  // For example, use /^\d+$/ for numeric IDs or a UUID regex for UUIDs.
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(userId)) {
    throw new TypeError("Invalid user id format");
  }

  const controller = new AbortController();
  let timeoutId;

  const onAbort = signal
    ? () => controller.abort(signal.reason)
    : undefined;

  if (signal?.aborted) {
    controller.abort(signal.reason);
  } else if (signal) {
    signal.addEventListener("abort", onAbort, { once: true });
  }

  if (timeoutMs > 0) {
    timeoutId = setTimeout(() => {
      controller.abort(new Error("Request timed out"));
    }, timeoutMs);
  }

  try {
    const response = await fetch(`/api/users/${encodeURIComponent(userId)}`, {
      method: "GET",
      headers: {
        Accept: "application/json",
      },
      credentials: "same-origin",
      signal: controller.signal,

      // Consider this for sensitive user data, but server Cache-Control
      // headers are more important.
      // cache: "no-store",
    });

    const contentType = response.headers.get("content-type") || "";
    const text = await response.text();

    const isJson = isJsonContentType(contentType);
    let body;

    if (text) {
      if (isJson) {
        try {
          body = JSON.parse(text);
        } catch (err) {
          throw new ApiError("Server returned invalid JSON", {
            status: response.status,
            statusText: response.statusText,
            body: text,
            cause: err,
          });
        }
      } else {
        body = text;
      }
    }

    if (!response.ok) {
      const message =
        body && typeof body === "object" && (body.message || body.error)
          ? String(body.message || body.error)
          : `Failed to fetch user: HTTP ${response.status}`;

      throw new ApiError(message, {
        status: response.status,
        statusText: response.statusText,
        body,
      });
    }

    if (!isJson) {
      throw new ApiError(
        `Expected JSON response, got ${contentType || "no content-type"}`,
        {
          status: response.status,
          statusText: response.statusText,
          body,
        }
      );
    }

    if (body == null) {
      throw new ApiError("Expected user object, got empty response", {
        status: response.status,
        statusText: response.statusText,
      });
    }

    return body;
  } finally {
    if (timeoutId) clearTimeout(timeoutId);

    if (signal && onAbort) {
      signal.removeEventListener("abort", onAbort);
    }
  }
}
```

One nuance: `return response.json()` without `await` is not itself a bug; async functions adopt returned promises. But once you want local error handling around JSON parsing, you should explicitly `await` or parse inside the function.
